ALTER TABLE subcontract_payments ADD COLUMN payment_channel VARCHAR(20) NULL AFTER amount, ADD COLUMN bank_payment_method VARCHAR(30) NULL AFTER payment_method, ADD COLUMN payment_account_id BIGINT UNSIGNED NULL AFTER bank_payment_method, ADD COLUMN payment_account_code_snapshot VARCHAR(30) NULL AFTER payment_account_id, ADD COLUMN payment_account_name_snapshot VARCHAR(190) NULL AFTER payment_account_code_snapshot, ADD COLUMN cheque_number VARCHAR(100) NULL AFTER reference_number, ADD COLUMN cheque_date DATE NULL AFTER cheque_number, ADD COLUMN cheque_due_date DATE NULL AFTER cheque_date, ADD COLUMN journal_entry_id BIGINT UNSIGNED NULL AFTER available_payment_snapshot, ADD KEY idx_subcontract_payments_account(payment_account_id), ADD UNIQUE KEY uq_subcontract_payments_journal(journal_entry_id), ADD CONSTRAINT fk_subcontract_payments_account FOREIGN KEY(payment_account_id) REFERENCES accounts(id) ON DELETE RESTRICT, ADD CONSTRAINT fk_subcontract_payments_journal FOREIGN KEY(journal_entry_id) REFERENCES journal_entries(id) ON DELETE RESTRICT, ADD CONSTRAINT chk_subcontract_payments_channel CHECK(payment_channel IS NULL OR payment_channel IN('cash','bank')), ADD CONSTRAINT chk_subcontract_payments_bank_method CHECK(bank_payment_method IS NULL OR bank_payment_method IN('bank_transfer','cheque','instapay','other'))
